"""Sparse-attribute handling.

The sparse attribute is a property the file system maintains per file.  It is
set through the ``FSCTL_SET_SPARSE`` control code on a handle opened for
writing, and it can be read back from ``GetFileAttributes``.

Two things are worth spelling out because the collector relies on them:

* setting the attribute never de-allocates anything.  A file that has already
  been extended densely keeps every cluster it holds; the attribute only allows
  the file to grow *holes* from now on.  That is why ``sparse_flag`` returns
  the state the file system reports instead of promising a compact file.
* the attribute cannot be set on an object that is not a file, or on a volume
  that does not understand sparse files.  Both cases are reported as
  ``WSParseError(kind="unsupported")`` rather than silently "succeeding".
"""

import os

from . import _winapi
from ._winapi import SPARSE_ATTRIBUTE, is_windows
from .errors import WSParseError


def _require_windows(path):
    if not is_windows():
        raise WSParseError(
            "the sparse attribute is a Windows file-system concept",
            kind="unsupported",
            path=path,
        )


def _require_regular_file(path):
    """Reject directories, devices and anything else that is not a plain file."""
    if not os.path.exists(path):
        raise WSParseError("no such file: %s" % path, kind="os", path=path)
    try:
        if _winapi.is_directory(path):
            raise WSParseError(
                "sparse files are not supported on this object",
                kind="unsupported",
                path=path,
            )
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc
    if not os.path.isfile(path):
        raise WSParseError(
            "sparse files are not supported on this object",
            kind="unsupported",
            path=path,
        )


def _require_volume_support(path):
    try:
        supported = _winapi.volume_supports_sparse(path)
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc
    if not supported:
        raise WSParseError(
            "the volume does not support sparse files",
            kind="unsupported",
            path=path,
        )


def _check_enabled(enabled):
    if isinstance(enabled, bool):
        return enabled
    if isinstance(enabled, int):
        return bool(enabled)
    raise WSParseError(
        "enabled must be a boolean, got %r" % (enabled,), kind="badarg"
    )


def sparse_state(path):
    """Return ``True`` when ``path`` currently carries the sparse attribute."""
    path = os.fspath(path)
    try:
        info = os.stat(path)
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc
    attributes = getattr(info, "st_file_attributes", 0)
    return bool(attributes & SPARSE_ATTRIBUTE)


def sparse_flag(path, enabled=True):
    """Turn the sparse attribute of ``path`` on or off.

    ``enabled`` defaults to ``True``.  Returns the state the file ends up in.

    Setting the attribute on a file that has already been extended densely
    succeeds and reports ``True`` -- but it does not, and cannot, give the
    clusters back: the file stays dense and :func:`~wsparse.disk_usage` keeps
    reporting the real (dense) occupancy.  Clearing the attribute stops the
    file from accepting new holes.
    """
    path = os.fspath(path)
    enabled = _check_enabled(enabled)
    if not os.path.exists(path):
        raise WSParseError("no such file: %s" % path, kind="os", path=path)
    _require_windows(path)
    _require_regular_file(path)
    _require_volume_support(path)

    try:
        with _winapi.open_handle(path, write=True) as handle:
            try:
                _winapi.set_sparse(handle.handle, enabled)
            except OSError as exc:
                if _winapi.is_unsupported(exc):
                    raise WSParseError(
                        "sparse files are not supported on this object",
                        kind="unsupported",
                        path=path,
                    ) from exc
                raise WSParseError(str(exc), kind="os", path=path) from exc
    except WSParseError:
        raise
    except OSError as exc:
        if getattr(exc, "errno", None) in (5, 32) or _winapi.is_unsupported(exc):
            # ERROR_ACCESS_DENIED / ERROR_SHARING_VIOLATION: the object cannot
            # be opened for writing, so the attribute cannot be maintained.
            raise WSParseError(str(exc), kind="unsupported", path=path) from exc
        raise WSParseError(str(exc), kind="os", path=path) from exc

    state = sparse_state(path)
    if state != enabled:
        raise WSParseError(
            "the file system kept the sparse attribute at %s" % (state,),
            kind="os",
            path=path,
        )
    return state

"""Shared plumbing for the space-accounting entry points.

Every public function of :mod:`wsparse` starts by turning the caller's path
into a concrete NTFS file and by classifying the object it names.  Doing that in
one place keeps the error taxonomy consistent:

``WSParseError(kind="os")``
    the object is missing, or could not be opened / read at all,
``WSParseError(kind="unsupported")``
    the object is not something the file system can hold a sparse range in --
    a directory, a named pipe, a device -- or the volume does not support
    sparse files at all.
"""

import os

from . import _winapi
from ._winapi import is_windows
from .errors import WSParseError


def normalize(path):
    """Return the caller's path as a string, unchanged in every other respect."""
    return os.fspath(path)


def check_object(path, need_write=False, need_sparse_volume=True):
    """Make sure ``path`` is a plain file we can run the sparse queries against.

    Raises :class:`~wsparse.errors.WSParseError` with a classified ``kind``.
    """
    if not is_windows():
        raise WSParseError(
            "sparse-file space accounting is a Windows/NTFS operation",
            kind="unsupported",
            path=path,
        )

    if not os.path.lexists(path):
        raise WSParseError("no such file: %s" % path, kind="os", path=path)

    # A directory (or a reparse point standing for one) has no byte ranges at
    # all: this is the "the object does not support sparse files" case.
    try:
        if _winapi.is_directory(path):
            raise WSParseError(
                "sparse files are not supported on this object",
                kind="unsupported",
                path=path,
            )
    except OSError as exc:
        if isinstance(exc, WSParseError):
            raise
        raise WSParseError(str(exc), kind="os", path=path) from exc

    try:
        is_regular = os.path.isfile(path)
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc
    if not is_regular:
        raise WSParseError(
            "sparse files are not supported on this object",
            kind="unsupported",
            path=path,
        )

    if need_sparse_volume:
        try:
            supported = _winapi.volume_supports_sparse(path)
        except OSError as exc:
            raise WSParseError(str(exc), kind="os", path=path) from exc
        if not supported:
            raise WSParseError(
                "the volume does not support sparse files",
                kind="unsupported",
                path=path,
            )


def classify_open_error(exc, path, need_write=False):
    """Turn an :class:`OSError` raised while opening ``path`` into a
    :class:`~wsparse.errors.WSParseError` with the right ``kind``."""
    code = getattr(exc, "winerror", None)
    if code is None:
        code = getattr(exc, "errno", None)
    if code in (2, 3):  # FILE_NOT_FOUND / PATH_NOT_FOUND
        return WSParseError(str(exc), kind="os", path=path)
    if code == 267 or _winapi.is_unsupported(exc):
        return WSParseError(
            "sparse files are not supported on this object",
            kind="unsupported",
            path=path,
        )
    return WSParseError(str(exc), kind="os", path=path)

