"""Disk-usage accounting for sink files."""

import os

from . import _winapi
from ._common import check_object, classify_open_error, os_error
from ._winapi import SPARSE_ATTRIBUTE
from .errors import WSParseError

#: Cluster size assumed when the volume will not tell us one.
_DEFAULT_CLUSTER = 4096


def _align_up(value, cluster):
    """Round ``value`` up to a whole number of clusters."""
    if cluster <= 1:
        return int(value)
    remainder = value % cluster
    if remainder:
        value += cluster - remainder
    return int(value)


def disk_usage(path):
    """Return the number of bytes ``path`` occupies on disk.

    This is what the quota tracker subtracts from the volume budget, so it has
    to describe the space the sink actually holds, not the number of bytes a
    reader would see.  A sparse sink reads as its whole logical length but only
    occupies the clusters behind its allocated ranges; the value returned here
    is therefore the compressed (on-disk) size the file system reports, which
    NTFS already rounds up to whole clusters.

    A directory -- or any other object that cannot hold sparse ranges -- raises
    ``WSParseError(kind="unsupported")``.
    """
    path = os.fspath(path)
    check_object(path)

    try:
        attributes = _winapi.get_file_attributes(path)
    except OSError as exc:
        raise os_error(exc, path) from exc
    is_sparse = bool(attributes & SPARSE_ATTRIBUTE)

    try:
        used = _winapi.get_compressed_file_size(path)
    except OSError as exc:
        # Not every volume answers GetCompressedFileSize (FAT32, some network
        # shares).  Fall back to the allocated ranges, and only then to the
        # logical length.
        if _winapi.is_unsupported(exc):
            used = None
        else:
            raise os_error(exc, path) from exc

    if used is None:
        used = _sum_allocated(path)

    if not is_sparse and used == 0:
        # A dense file always occupies its clusters; never report zero for a
        # file that has a logical length.
        try:
            used = os.path.getsize(path)
        except OSError as exc:
            raise os_error(exc, path) from exc

    return _align_up(used, _DEFAULT_CLUSTER)


def _sum_allocated(path):
    """Sum the allocated ranges of ``path`` as a fallback for ``disk_usage``."""
    try:
        with _winapi.open_handle(path) as handle:
            ranges = _winapi.query_allocated_ranges(handle.handle)
    except OSError as exc:
        raise classify_open_error(exc, path) from exc
    total = 0
    for start, end in ranges:
        total += end - start
    return total

"""Pre-allocation of sink files.

On NTFS a sink is pre-allocated by making it *sparse* and then extending it to
its final length.  Marking the file sparse and growing the end-of-file costs the
file system nothing but a directory entry: the bytes between the old end and the
new end are a hole, they read back as zeros and they occupy no clusters.  Only
the regions the collector actually writes into ever reach the disk, which is
what lets the transfer layer resume a partial download from
:func:`~wsparse.allocated_ranges`.

Writing zeros over the tail instead -- what an earlier revision of this module
did -- allocates every cluster of the sink up front.  That is the bug the
collector hit: pre-allocating a 1 GiB shard took minutes and filled the volume.
"""

import os

from . import _winapi
from ._common import os_error, unsupported
from .errors import WSParseError

#: The tail of a pre-allocated sink is punched out in whole chunks of this
#: size.  ``FSCTL_SET_ZERO_DATA`` handles far more in one call, but keeping the
#: chunks bounded means a 1 GiB reservation stays a handful of cheap ioctls
#: instead of one enormous structure.
_BLOCK = 1 << 20


def _check_size(size):
    if isinstance(size, bool) or not isinstance(size, int):
        raise WSParseError("size must be an integer, got %r" % (size,), kind="badarg")
    if size < 0:
        raise WSParseError("size must not be negative, got %r" % (size,), kind="badarg")


def _create(path):
    """Make sure ``path`` exists, without ever touching its current content."""
    try:
        handle = open(path, "r+b")
    except FileNotFoundError:
        try:
            handle = open(path, "x+b")
        except FileExistsError:
            handle = open(path, "r+b")
    handle.close()


def _open_for_update(path):
    try:
        return open(path, "r+b")
    except FileNotFoundError:
        try:
            return open(path, "w+b")
        except OSError as exc:
            raise WSParseError(str(exc), kind="os", path=path) from exc
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc


def _punch_tail(handle, start, end):
    """De-allocate ``[start, end)`` of an open sparse file."""
    while start < end:
        stop = start + _BLOCK
        if stop > end:
            stop = end
        _winapi.set_zero_data(handle, start, stop)
        start = stop


def _windows_preallocate(path, size):
    if os.path.isdir(path):
        raise unsupported(path)
    try:
        if not _winapi.volume_supports_sparse(path):
            raise WSParseError(
                "the volume does not support sparse files",
                kind="unsupported",
                path=path,
            )
    except OSError as exc:
        raise os_error(exc, path) from exc

    try:
        _create(path)
    except OSError as exc:
        raise os_error(exc, path) from exc

    try:
        with _winapi.open_handle(path, write=True) as opened:
            handle = opened.handle

            # 1. The file has to be sparse *before* it grows, otherwise the
            #    file system allocates clusters for every byte we add.
            try:
                _winapi.set_sparse(handle, True)
            except OSError as exc:
                if _winapi.is_unsupported(exc):
                    raise unsupported(path) from exc
                raise os_error(exc, path) from exc

            # 2. Grow the end-of-file.  For a sparse file this is a metadata
            #    operation: the tail stays a hole.
            current = _winapi.get_file_size(handle)
            if size > current:
                try:
                    _winapi.set_end_of_file(handle, size)
                except OSError as exc:
                    raise os_error(exc, path) from exc
                # 3. Make the hole explicit.  This also gives the space back
                #    when the tail used to hold real clusters.
                try:
                    _punch_tail(handle, current, size)
                except OSError as exc:
                    if not _winapi.is_unsupported(exc):
                        raise os_error(exc, path) from exc
                final = _winapi.get_file_size(handle)
            else:
                # Pre-allocation never shrinks a sink.
                final = current
            return int(final)
    except WSParseError:
        raise
    except OSError as exc:
        raise os_error(exc, path) from exc


def _posix_preallocate(path, size):
    """Best-effort pre-allocation on platforms without sparse-file ioctls.

    The collector only ships on Windows; this keeps the module usable (and its
    tests meaningful) elsewhere without pretending to punch holes.
    """
    handle = _open_for_update(path)
    try:
        handle.seek(0, os.SEEK_END)
        if handle.tell() < size:
            handle.truncate(size)
        handle.flush()
        try:
            os.fsync(handle.fileno())
        except OSError:
            pass
        handle.seek(0, os.SEEK_END)
        return handle.tell()
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc
    finally:
        handle.close()


def preallocate(path, size):
    """Grow ``path`` to ``size`` bytes and reserve the space for it.

    The sink is created when it does not exist yet and is marked sparse, so the
    reserved tail is a hole: it reads back as zeros, it holds no clusters, and
    the writer can fill it in later without the file having to grow.  Existing
    content is preserved; the file is only ever extended, never shrunk.  The
    call is idempotent -- calling it again with the same ``size`` leaves the
    file untouched.

    Returns the resulting file length in bytes.

    Raises ``WSParseError(kind="unsupported")`` when the object or the volume
    cannot hold a sparse file, and ``WSParseError(kind="badarg")`` when ``size``
    is not a non-negative integer.
    """
    _check_size(size)
    path = os.fspath(path)
    if not _winapi.is_windows():
        return _posix_preallocate(path, size)
    return _windows_preallocate(path, size)

