            except OSError as exc:
                if _winapi.is_unsupported(exc):
                    raise unsupported(path) from exc
                raise os_error(exc, path) from exc

            # 2. Grow the end-of-file.  For a sparse file this is a metadata
            #    operation; the tail stays a hole.
            current = _winapi.get_file_size(handle)
            if size <= current:
                # Pre-allocation never shrinks a sink, and it never gives the
                # clusters of data that is already there back.
                return int(current)
            try:
                _winapi.set_end_of_file(handle, size)
            except OSError as exc:
                raise os_error(exc, path) from exc

            # 3. Make the hole explicit.  This is what turns a tail that used to
            #    hold real clusters -- or that an earlier revision filled with
            #    zeros -- back into space that is not occupied.
            _punch(handle, current, size, path)

            return int(_winapi.get_file_size(handle))
    except WSParseError:
        raise
    except OSError as exc:
        raise os_error(exc, path) from exc


def _posix_preallocate(path, size):
    """Best-effort pre-allocation on platforms without sparse-file ioctls.

    The collector only ships on Windows; this keeps the module importable and
    usable elsewhere without pretending that it can punch holes.
    """
    handle = _open_for_update(path)
    try:
        handle.seek(0, os.SEEK_END)
        if handle.tell() < size:
            handle.truncate(size)
        handle.flush()
        try:
            os.fsync(handle.fileno())
        except OSError:
            pass
        handle.seek(0, os.SEEK_END)
        return handle.tell()
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc
    finally:
        handle.close()


def preallocate(path, size):
    """Grow ``path`` to ``size`` bytes and reserve the space for it.

    The sink is created when it does not exist yet and is marked sparse, so the
    reserved tail is a hole: it reads back as zeros, it holds no clusters, and
    the writer can fill it in later without the file having to grow.  Existing
    content is preserved; the file is only ever extended, never shrunk.  The
    call is idempotent -- calling it again with the same ``size`` leaves the
    file untouched.

    Returns the resulting file length in bytes.

    Raises ``WSParseError(kind="badarg")`` when ``size`` is not a non-negative
    integer, ``WSParseError(kind="unsupported")`` when the object or the volume
    cannot hold a sparse file, and ``WSParseError(kind="os")`` for any other
    operating-system failure.
    """
    _check_size(size)
    path = os.fspath(path)
    if not _winapi.is_windows():
        return _posix_preallocate(path, size)
    return _windows_preallocate(path, size)
